// One item per feed entry comes in; keep the newest one this workflow has not
// already turned into a content kit. Run summary records the guid of the last
// fully rendered kit in workflow static data — but n8n only PERSISTS static data
// on production executions, so while the workflow is inactive your manual test
// runs never advance the marker and always rebuild the newest post.
const items = $input.all().map((i) => i.json).filter((it) => it && (it.title || it.link));
if (!items.length) {
  throw new Error('The feed returned no readable posts. Check feedUrl in Config — it must be an RSS or Atom feed URL, like https://blog.google/rss/.');
}

const ts = (it) => {
  const t = Date.parse(it.isoDate || it.pubDate || '');
  return Number.isFinite(t) ? t : null;
};
// Newest first when the feed provides dates. Feeds without dates keep feed
// order — virtually every feed lists newest first.
const dated = items.map((it, i) => ({ it, i, t: ts(it) }));
if (dated.some((d) => d.t !== null)) {
  dated.sort((a, b) => ((b.t == null ? -Infinity : b.t) - (a.t == null ? -Infinity : a.t)) || a.i - b.i);
}
const post = dated[0].it;

const link = String(post.link || '').trim();
const guid = String(post.guid || link || post.title).trim();

const store = $getWorkflowStaticData('global');
if (store.lastGuid && store.lastGuid === guid) {
  return [{ json: { found: false, reason: 'Newest post already turned into a kit (guid unchanged since the last successful production run).', title: String(post.title || ''), guid } }];
}

// Feed body: full content when the feed carries it, else the snippet. Tags are
// stripped here — raw RSS HTML never reaches a layout.
const raw = String(post['content:encoded'] || post.content || post.summary || post.contentSnippet || post.description || '');
const feedText = raw
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&#39;|&apos;/g, "'").replace(/&quot;/g, '"').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/\s+/g, ' ').trim();

// n8n's Code-node sandbox has NO `URL` global (typeof URL === 'undefined'), so
// `new URL(link)` throws ReferenceError and this catch silently left the domain
// blank — every live render then fell back to the placeholder host. Parse the
// host off the string instead: works in n8n AND in plain node.
let domain = '';
const hostMatch = link.match(/^https?:\/\/([^\/?#]+)/i);
if (hostMatch) domain = hostMatch[1].replace(/^www\./, '').replace(/:\d+$/, '');

return [{
  json: {
    found: true,
    title: String(post.title || '').replace(/\s+/g, ' ').trim(),
    link,
    guid,
    domain,
    published: post.isoDate || post.pubDate || null,
    feedText,
  },
}];

// The newest post already has a kit, so there is nothing to do until the blog
// publishes again. This is a normal, successful outcome — not an error.
const picked = $('Pick newest post').first().json;
return [{
  json: {
    rendered: false,
    reason: picked.reason || 'No new post.',
    newestPost: picked.title,
    nextStep: 'Run again after the next post is published. (Static data only persists on production executions, so manual test runs always see the newest post as new.)',
  },
}];

// Prefer the post's real page text over the feed excerpt: many feeds (the
// default one included) carry a single-line snippet, and copy written from a
// snippet forces the model to invent the rest. The page fetch is best-effort —
// when it fails or the page is thin the feed text is used instead, and the
// prompt's no-invention rule keeps the kit honest either way.
const cfg = $('Config').first().json;
const post = $('Pick newest post').first().json;
const res = $input.first().json || {};

const maxChars = Math.max(600, Number(cfg.maxPromptChars || 4000));
let pageText = '';
if (typeof res.data === 'string' && res.data.length > 200) {
  let html = res.data;
  const section = /<article[\s\S]*?<\/article>/i.exec(html) || /<main[\s\S]*?<\/main>/i.exec(html) || /<body[\s\S]*?<\/body>/i.exec(html);
  html = section ? section[0] : html;
  pageText = html
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ')
    .replace(/<svg[\s\S]*?<\/svg>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&#39;|&apos;/g, "'").replace(/&quot;/g, '"').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/\s+/g, ' ').trim();
}

const useable = pageText.length > Math.max(400, post.feedText.length * 1.5) ? pageText : post.feedText;
const articleSource = useable === pageText ? 'page' : 'feed';
const article = useable.slice(0, maxChars);

const domain = String(cfg.domainOverride || post.domain || 'the blog').trim();

const promptText = 'Blog post title: ' + post.title + '\n'
  + 'Blog domain: ' + domain + '\n'
  + '\nArticle text (may be partial):\n"""\n' + article + '\n"""\n'
  + '\nWrite the copy for a three-piece social kit about this post: a LinkedIn video, an X teaser video and an Open Graph share image. Rules:\n'
  + '1. Use ONLY facts that appear in the article text above. If the text is thin, stay general — NEVER invent numbers, names, dates or claims that are not in it.\n'
  + '2. liHeadline: the LinkedIn cover headline. TEN WORDS OR FEWER. A statement, not a question, no ending period.\n'
  + '3. liPoints: EXACTLY three takeaways from the article, in the order it makes them. EIGHT WORDS OR FEWER each, no ending period, no numbering.\n'
  + '4. teaserHook: the first line of the X teaser. TWELVE WORDS OR FEWER, the single most interesting idea.\n'
  + '5. teaserLine: the follow-up line. SIXTEEN WORDS OR FEWER, one concrete reason to read the post.\n'
  + '6. ogTitle: the share-image title. NINE WORDS OR FEWER, no ending period.\n'
  + '7. ogKicker: a category label for the share image. FOUR WORDS OR FEWER, e.g. PRODUCTIVITY or ENGINEERING.\n'
  + '8. Plain ASCII only: no emoji, markdown, quotes, brackets, hashtags or curly punctuation.\n'
  + '\nReturn exactly this JSON shape:\n'
  + '{\n  "liHeadline": "...",\n  "liPoints": ["...", "...", "..."],\n  "teaserHook": "...",\n  "teaserLine": "...",\n  "ogTitle": "...",\n  "ogKicker": "..."\n}';

return [{ json: { promptText, articleSource, articleChars: article.length } }];

// Parses the editor's JSON and sanity-checks it. The builder clamps every
// string again by words and characters, so this node only has to guarantee the
// shape: three usable points and the four headline strings.
const post = $('Pick newest post').first().json;
const prep = $('Prepare kit prompt').first().json;
const res = $input.first().json;

const content = res && res.choices && res.choices[0] && res.choices[0].message ? res.choices[0].message.content : null;
if (!content) throw new Error('The model returned no content: ' + JSON.stringify(res).slice(0, 400));

let kit;
try { kit = JSON.parse(content); } catch (e) {
  const m = /\{[\s\S]*\}/.exec(content);
  if (!m) throw new Error('The model did not return JSON:\n' + content.slice(0, 400));
  kit = JSON.parse(m[0]);
}

// Models slip curly quotes and dashes in even when told not to, and those glyphs
// are missing from some display faces. Normalise to ASCII before anything is
// counted or measured.
const toAscii = (s) => String(s == null ? '' : s)
  .replace(/[\u2018\u2019\u02BC]/g, "'")
  .replace(/[\u201C\u201D]/g, '"')
  .replace(/[\u2013\u2014]/g, '-')
  .replace(/\u2026/g, '...')
  .replace(/\s+/g, ' ')
  .trim();

const clean = {
  liHeadline: toAscii(kit.liHeadline).replace(/[.]+$/, ''),
  liPoints: (Array.isArray(kit.liPoints) ? kit.liPoints : []).map((p) => toAscii(p).replace(/^[0-9]+[.)\s]+/, '').replace(/[.]+$/, '')).filter(Boolean).slice(0, 3),
  teaserHook: toAscii(kit.teaserHook),
  teaserLine: toAscii(kit.teaserLine),
  ogTitle: toAscii(kit.ogTitle).replace(/[.]+$/, ''),
  ogKicker: toAscii(kit.ogKicker),
};

const missing = ['liHeadline', 'teaserHook', 'teaserLine', 'ogTitle'].filter((k) => !clean[k]);
if (missing.length) {
  throw new Error('The model left ' + missing.join(', ') + ' empty. Retry, or use a stronger model in Config.llmModel.');
}
if (clean.liPoints.length < 2) {
  throw new Error('The model returned only ' + clean.liPoints.length + ' usable liPoints (need 2-3). Retry, or use a stronger model in Config.llmModel.');
}

return [{
  json: {
    kit: clean,
    articleSource: prep.articleSource,
    articleChars: prep.articleChars,
    post: { title: post.title, link: post.link, domain: post.domain, published: post.published, guid: post.guid },
  },
}];

// A music bed is a nice-to-have; a broken or oversized one must never fail the
// run. The renderer rejects any audio asset over the plan cap, so probe the URL
// with a HEAD request first and drop the bed rather than the whole kit.
const cfg = $('Config').first().json;
const kit = $('Parse kit copy').first().json.kit;
const probe = $input.first().json || {};

const url = String(cfg.musicUrl || '').trim();
const limit = Number(cfg.maxMusicBytes == null ? 5242880 : cfg.maxMusicBytes);

let music = null;
let musicNote;
if (!url) {
  musicNote = 'No musicUrl set in Config — the two videos render silent.';
} else {
  const status = Number(probe.statusCode);
  const headers = probe.headers || {};
  const bytes = Number(headers['content-length'] || headers['Content-Length'] || 0);
  if (status !== 200) {
    musicNote = 'Music bed skipped: HEAD ' + url + ' returned HTTP ' + (status || '?') + '. Rendering without music.';
  } else if (bytes && bytes > limit) {
    musicNote = 'Music bed skipped: ' + bytes + ' bytes is over the ' + limit + '-byte plan cap. Rendering without music.';
  } else {
    music = { src: url, bytes: bytes || null };
    musicNote = 'Music bed reachable (' + (bytes || 'unknown') + ' bytes), under the ' + limit + '-byte cap.';
  }
}

return [{ json: { kit, music, musicNote } }];

// === buildKit — identical to the frame-reviewed standalone builder ===
// Turns ONE blog post plus one LLM copy pass into a three-piece content kit
// that shares a single brand system:
//   1. LinkedIn square video   1080x1080 mp4  (kicker, headline, 3 point cards, CTA outro)
//   2. X teaser video          1280x720  mp4  (hook, one line, domain pill)
//   3. Open Graph share image  1200x630  png  (editorial split layout)
// Every piece is built from the SAME palette, type scale and chrome helpers, so
// the three assets read as one campaign. Text never comes from raw RSS HTML —
// only from the clamped, HTML-escaped copy the model returned.
function buildKit(config, post, source) {
  const cfg = config || {};
  const clean = (v) => String(v == null ? '' : v).replace(/\s+/g, ' ').trim();
  const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const round = (n) => Math.round(n * 100) / 100;
  const clamp = (n, lo, hi) => Math.min(hi, Math.max(lo, n));

  // ---- palette ------------------------------------------------------------
  const safeHex = (v, fallback) => (/^#[0-9a-fA-F]{6}$/.test(clean(v)) ? clean(v) : fallback);
  const ink = safeHex(cfg.brandInk, '#0B0F1A');
  const accent = safeHex(cfg.brandAccent, '#FFB454');
  const textColor = safeHex(cfg.textColor, '#F2F5FB');
  const muted = safeHex(cfg.mutedColor, '#8D99B4');
  const headlineFont = clean(cfg.headlineFont) || 'Instrument Serif';
  const uiFont = clean(cfg.uiFont) || 'Space Grotesk';

  const hexToRgb = (h) => { const n = parseInt(h.slice(1), 16); return [(n >> 16) & 255, (n >> 8) & 255, n & 255]; };
  const rgba = (h, a) => { const c = hexToRgb(h); return 'rgba(' + c[0] + ',' + c[1] + ',' + c[2] + ',' + a + ')'; };
  // A slightly lifted / dropped tone derived from the ink, used for card
  // interiors and the stops of every background gradient.
  const lift = (h, amt) => { const c = hexToRgb(h); const f = (x) => Math.max(0, Math.min(255, Math.round(x + amt))); return 'rgb(' + f(c[0]) + ',' + f(c[1]) + ',' + f(c[2]) + ')'; };

  // ---- copy clamps --------------------------------------------------------
  // The prompt asks for short copy, but a model that ignores the word budget
  // must never be able to overflow a layout — so every string is clamped HERE
  // as well, by words first and then by characters.
  // Truncation is signalled with a real ellipsis so a clamped line reads as a
  // deliberate cut instead of a sentence that lost its ending.
  const clampWords = (v, maxWords, maxChars) => {
    const original = clean(v);
    let s = original;
    const words = s.split(' ').filter(Boolean);
    if (words.length > maxWords) s = words.slice(0, maxWords).join(' ');
    if (s.length > maxChars) {
      const cut = s.slice(0, maxChars);
      const lastSpace = cut.lastIndexOf(' ');
      s = lastSpace > maxChars * 0.6 ? cut.slice(0, lastSpace) : cut;
    }
    if (s !== original) s = s.replace(/[\s,;:.\-]+$/, '') + '…';
    return s;
  };
  // Labels (kicker, CTA, section eyebrow) are chrome, not prose — a trailing
  // ellipsis there would look like a bug, so they clamp silently.
  const clampLabel = (v, maxWords, maxChars) => clampWords(v, maxWords, maxChars).replace(/…$/, '');

  const kit = source.kit || {};
  const liHeadline = clampWords(kit.liHeadline, 10, 90);
  const liPoints = (Array.isArray(kit.liPoints) ? kit.liPoints : [])
    .map((p) => clampWords(p, 8, 66))
    .filter(Boolean)
    .slice(0, 3);
  const teaserHook = clampWords(kit.teaserHook, 12, 72);
  const teaserLine = clampWords(kit.teaserLine, 16, 112);
  const ogTitle = clampWords(kit.ogTitle, 9, 72);

  if (!liHeadline) throw new Error('The model returned no liHeadline. Retry, or use a stronger model in Config.llmModel.');
  if (!teaserHook) throw new Error('The model returned no teaserHook. Retry, or use a stronger model in Config.llmModel.');
  if (!ogTitle) throw new Error('The model returned no ogTitle. Retry, or use a stronger model in Config.llmModel.');
  if (liPoints.length < 2) throw new Error('The model returned only ' + liPoints.length + ' usable liPoints (need 2-3). Retry, or use a stronger model in Config.llmModel.');

  const brandName = clampLabel(cfg.brandName, 6, 40) || 'Your blog';
  const domain = clampLabel(cfg.domainOverride || post.domain, 4, 40) || 'yourblog.com';
  const kicker = (clampLabel(cfg.kickerText, 4, 22) || 'NEW POST').toUpperCase();
  const ogKicker = (clampLabel(kit.ogKicker, 4, 22) || kicker).toUpperCase();
  const ctaText = clampLabel(cfg.ctaText, 6, 34) || 'Read the full post';
  const pointsLabel = (clampLabel(cfg.pointsLabel, 4, 22) || 'What is inside').toUpperCase();
  const subheadText = (clampLabel(cfg.subheadText, 6, 34) || '{n} takeaways inside').replace('{n}', String(liPoints.length));

  // ---- shared type helper -------------------------------------------------
  // Greedy word-wrap estimate. avgEm is the average glyph advance as a share of
  // the font size, measured against the rendered reference layouts: ~0.46 for
  // the serif headline face, ~0.56 for the sans UI face.
  const wrapLines = (text, fontPx, boxPx, avgEm) => {
    const perLine = Math.max(6, Math.floor(boxPx / (fontPx * avgEm)));
    let lines = 1;
    let used = 0;
    for (const w of String(text).split(' ')) {
      const need = used === 0 ? w.length : used + 1 + w.length;
      if (need <= perLine) { used = need; continue; }
      lines += 1;
      used = Math.min(w.length, perLine);
    }
    return lines;
  };

  // The render API only allows letters, digits, spaces, _ and - in `name`.
  const slug = (s) => String(s).toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 46);
  const postSlug = slug(post.title || liHeadline) || 'post';

  // ---- shared chrome ------------------------------------------------------
  // Pills declare style.color = accent (what the element reads as) while the
  // inner html paints the label on the accent fill — the validator's contrast
  // lint compares style.color against the scene background, and an accent pill
  // is exactly an accent-on-ink element.
  const chipHtml = (label, size, padY, padX) =>
    "<div style='display:inline-block; background:" + rgba(accent, 0.14) + '; border:1.5px solid ' + rgba(accent, 0.55) + '; color:' + accent +
    '; border-radius:999px; padding:' + padY + 'px ' + padX + 'px; font-size:' + size + 'px; font-weight:700; letter-spacing:' + Math.round(size * 0.2) + "px;'>" + esc(label) + '</div>';

  // The footer line carries brand + domain. It has no explicit element width,
  // so it must never be able to grow past its column: step the size down until
  // the estimated advance fits the column it lives in.
  const footChars = brandName.length + domain.length + 6;
  const footSize = (size, maxWidth) => {
    let s = size;
    while (s > 17 && footChars * s * 0.56 > maxWidth) s -= 1;
    return s;
  };
  const footHtml = (size, maxWidth) => {
    const s = footSize(size, maxWidth);
    return "<div style='color:" + textColor + '; font-size:' + s + "px; font-weight:700; letter-spacing:1px;'>" + esc(brandName) +
      "<span style='color:" + rgba(muted, 0.9) + "; font-weight:500;'>&nbsp;&nbsp;&middot;&nbsp;&nbsp;" + esc(domain) + '</span></div>';
  };

  // Background plate shared by every piece: gradient, a soft accent glow placed
  // per scene, and a hairline frame that keeps the composition inside a card.
  const plate = (w, h, id, glowX, glowY, inset, radius) =>
    "<svg width='" + w + "' height='" + h + "' viewBox='0 0 " + w + ' ' + h + "' xmlns='http://www.w3.org/2000/svg'><defs>" +
    "<linearGradient id='" + id + "g' x1='0' y1='0' x2='1' y2='1'><stop offset='0' stop-color='" + lift(ink, 12) + "'/><stop offset='0.55' stop-color='" + ink + "'/><stop offset='1' stop-color='" + lift(ink, -4) + "'/></linearGradient>" +
    "<radialGradient id='" + id + "r' cx='" + glowX + "' cy='" + glowY + "' r='0.72'><stop offset='0' stop-color='" + accent + "' stop-opacity='0.26'/><stop offset='1' stop-color='" + accent + "' stop-opacity='0'/></radialGradient>" +
    "</defs><rect width='" + w + "' height='" + h + "' fill='url(#" + id + "g)'/><rect width='" + w + "' height='" + h + "' fill='url(#" + id + "r)'/>" +
    "<rect x='" + inset + "' y='" + inset + "' width='" + (w - inset * 2) + "' height='" + (h - inset * 2) + "' rx='" + radius + "' fill='none' stroke='rgba(255,255,255,0.09)' stroke-width='1.5'/></svg>";

  // ---- pacing -------------------------------------------------------------
  // A scene transition overlaps its two scenes, so every non-last scene is
  // padded by transitionDuration and the run still lands on the target length.
  const transition = clean(cfg.sceneTransition) || null;
  const tDur = transition ? clamp(Number(cfg.transitionSeconds == null ? 0.5 : cfg.transitionSeconds), 0.1, 1.2) : 0;
  const sceneOf = (id, visible, isLast, visuals) => {
    const scene = {
      id,
      duration: round(visible + (isLast ? 0 : tDur)),
      backgroundColor: ink,
      visuals,
    };
    if (!isLast && transition) {
      scene.transition = transition;
      scene.transitionDuration = tDur;
    }
    return scene;
  };

  const music = source.music && source.music.src ? source.music : null;
  const musicVolume = clamp(Number(cfg.musicVolume == null ? 0.16 : cfg.musicVolume), 0, 1);
  // NOTE: no `track` on audios — the render API rejects audios[].track.
  const audiosFor = () => (music ? [{ src: music.src, volume: musicVolume }] : []);
  const frameRate = clamp(Math.round(Number(cfg.frameRate == null ? 30 : cfg.frameRate)), 1, 60);

  const outputs = [];

  // =========================================================================
  // 1. LinkedIn square video — 1080x1080
  // =========================================================================
  if (cfg.makeLinkedInVideo !== false) {
    const W = 1080;
    const target = clamp(Number(cfg.linkedInSeconds == null ? 20 : cfg.linkedInSeconds), 12, 45);
    const vCover = round(target * 0.26);
    const vPoints = round(target * 0.52);
    const vOutro = round(target - vCover - vPoints);
    const scenes = [];

    // --- scene 1: cover ---
    {
      const dur = round(vCover + tDur);
      const hl = liHeadline.length;
      const hlSize = hl <= 34 ? 104 : hl <= 55 ? 88 : hl <= 76 ? 76 : 64;
      const hlLines = wrapLines(liHeadline, hlSize, 912, 0.46);
      // The headline block is optically centred in the space between the kicker
      // and the footer; the accent rule rides just above it and the takeaway
      // count just below, so a one-line headline and a three-line headline both
      // look deliberately placed instead of floating.
      const hlBlockH = Math.round(hlLines * hlSize * 1.08);
      const ruleY = Math.max(232, 556 - Math.round(hlBlockH / 2) - 62);
      const subY = Math.min(846, 556 + Math.round(hlBlockH / 2) + 54);
      scenes.push(sceneOf('cover', vCover, false, [
        { type: 'SVG', width: W, height: W, track: 0, enterBegin: 0, exitEnd: dur, svg: plate(W, W, 'bckC', 0.86, 0.1, 40, 30) },
        {
          type: 'SVG', width: W, height: W, track: 1, enterBegin: 0.5, enterEnd: 1.05, enterAnimation: 'wiperight', exitEnd: dur,
          svg: "<svg width='" + W + "' height='" + W + "' viewBox='0 0 " + W + ' ' + W + "' xmlns='http://www.w3.org/2000/svg'><rect x='84' y='" + ruleY + "' width='168' height='6' rx='3' fill='" + accent + "'/></svg>",
        },
        {
          // On screen from frame zero: the very first frame of the video is
          // never an empty plate.
          type: 'TEXT', x: 84, y: 96, anchor: 'top-left', track: 2, enterBegin: 0, exitEnd: dur,
          style: { fontFamily: uiFont, color: accent },
          html: chipHtml(kicker, 24, 14, 32),
        },
        {
          // Multi-line copy always enters on a plain fade — a directional wipe
          // reveals the last line first, which reads as a glitch mid-animation.
          type: 'TEXT', x: 84, y: 556, width: 912, anchor: 'center-left', track: 3, enterBegin: 0.35, enterEnd: 1.05, enterAnimation: 'fade', exitEnd: dur,
          style: { fontFamily: headlineFont, color: textColor },
          html: "<div style='color:" + textColor + '; font-size:' + hlSize + "px; line-height:1.08; font-weight:400; letter-spacing:-0.01em;'>" + esc(liHeadline) + '</div>',
        },
        {
          type: 'TEXT', x: 84, y: subY, anchor: 'top-left', track: 4, enterBegin: 1.25, enterEnd: 1.75, enterAnimation: 'fade', exitEnd: dur,
          style: { fontFamily: uiFont, color: muted },
          html: "<div style='color:" + muted + "; font-size:28px; font-weight:600; letter-spacing:3px;'>" + esc(subheadText) + '</div>',
        },
        {
          type: 'TEXT', x: 84, y: 946, anchor: 'top-left', track: 5, enterBegin: 0.9, enterEnd: 1.35, enterAnimation: 'fade', exitEnd: dur,
          style: { fontFamily: uiFont, color: textColor },
          html: footHtml(28, 912),
        },
      ]));
    }

    // --- scene 2: point cards ---
    {
      const dur = round(vPoints + tDur);
      const n = liPoints.length;
      const cardH = 176;
      const gap = 22;
      const blockH = n * cardH + (n - 1) * gap;
      const top = Math.round(566 - blockH / 2); // block centred between the eyebrow and the footer
      const visuals = [
        { type: 'SVG', width: W, height: W, track: 0, enterBegin: 0, exitEnd: dur, svg: plate(W, W, 'bckP', 0.12, 0.92, 40, 30) },
        {
          type: 'TEXT', x: 84, y: 176, anchor: 'top-left', track: 1, enterBegin: 0, exitEnd: dur,
          style: { fontFamily: uiFont, color: accent },
          html: "<div style='color:" + accent + "; font-size:24px; font-weight:700; letter-spacing:6px;'>" + esc(pointsLabel) + '</div>',
        },
        {
