// === n8n glue ===
const config = $('Config').first().json;
const post = $('Pick newest post').first().json;
const source = $('Music guard').first().json;

// One item per kit piece: the validate -> render chain runs per item, so a
// single run produces two videos and one image side by side.
const built = buildKit(config, post, source);
return built.map((b) => ({ json: b, pairedItem: { item: 0 } }));

// The free validate endpoint runs the exact pipeline a render submission runs,
// so a failure here is a payload bug — surface the field list for the piece that
// broke instead of a generic HTTP error. Runs once per kit piece.
const built = $('Build project JSON').all();
return $input.all().map((res, i) => {
  const status = res.json.statusCode;
  const body = res.json.body || {};
  const meta = built[i].json.meta;
  if (status !== 200 || body.valid === false) {
    const details = Array.isArray(body.details)
      ? body.details.map((d) => '  - ' + d.field + ': ' + d.message).join('\n')
      : JSON.stringify(body).slice(0, 500);
    throw new Error('Zvid rejected the ' + meta.label + ' (HTTP ' + status + '): ' + (body.message || body.error) + '\n' + details);
  }
  return {
    json: { ...built[i].json, creditsRequired: body.creditsRequired, warnings: body.warnings || [] },
    pairedItem: { item: i },
  };
});

// Dry run: everything except the paid renders. One item per kit piece, each with
// its own editorLink, plus the total the whole kit would cost. Nothing is spent
// and the feed position is not advanced, so the next real run builds the same kit.
const cfg = $('Config').first().json;
const checked = $('Check validation').all();
const kitCreditsTotal = checked.reduce((n, c) => n + (Number(c.json.creditsRequired) || 0), 0);

return $input.all().map((res, i) => {
  const d = checked[i].json;
  let editorLink = null;
  let draftId = null;
  const project = res.json && res.json.project;
  if (project && project.id) {
    draftId = project.id;
    editorLink = String(cfg.editorUrl || 'https://editor.zvid.io').replace(/\/+$/, '') + '/?project=' + project.id;
  }
  return {
    json: {
      dryRun: true,
      kind: d.meta.kind,
      label: d.meta.label,
      dimensions: d.meta.dimensions,
      format: d.meta.format,
      seconds: d.meta.totalSeconds,
      creditsRequired: d.creditsRequired,
      kitCreditsTotal,
      kitPieces: d.meta.of,
      postTitle: d.meta.postTitle,
      postLink: d.meta.postLink,
      musicNote: d.meta.musicNote,
      editorLink,
      draftId,
      warnings: d.warnings,
      nextStep: editorLink
        ? 'Open editorLink to preview this piece. Set dryRun to false in Config to render the whole kit for real.'
        : 'Set dryRun to false in Config to render the whole kit for real.',
      payload: d.payload,
    },
    pairedItem: { item: i },
  };
});

// The render response replaces the item, so glue the jobId back onto the kit
// piece it belongs to. An index zip is safe here: same items, same order, and
// the poll loop has not started yet.
const checked = $('Check validation').all();
return $input.all().map((res, i) => {
  const jobId = res.json.jobId || res.json.id;
  if (!jobId) {
    throw new Error('Render submission returned no jobId: ' + JSON.stringify(res.json).slice(0, 300));
  }
  const { payload, ...rest } = checked[i].json;
  return { json: { ...rest, jobId }, pairedItem: { item: i } };
});

// The status response replaces the item again — zip it back with whatever
// entered this poll iteration. Wait passes items through unchanged and the
// status node runs once per item in order, so index i pairs correctly on every
// lap, including the laps where some pieces have already finished.
const carried = $('Wait').all();
return $input.all().map((res, i) => {
  const job = res.json;
  return {
    json: {
      ...carried[i].json,
      state: job.state,
      failedReason: job.failedReason || null,
      result: job.result || null,
    },
    pairedItem: { item: i },
  };
});

// Fails fast on a failed render and stops the poll loop at the timeout. Pieces
// that already finished have gone down the true branch, so this only ever sees
// the ones still in the queue.
const cfg = $('Config').first().json;
for (const item of $input.all()) {
  if (item.json.state === 'failed') {
    throw new Error('Render failed for the ' + item.json.meta.label + ': ' + (item.json.failedReason || 'no reason given') + '.');
  }
}
const maxPolls = Math.ceil((Number(cfg.timeoutMinutes || 20) * 60) / Number(cfg.pollSeconds || 10));
if ($runIndex + 1 >= maxPolls) {
  throw new Error('The kit did not finish rendering within ' + cfg.timeoutMinutes + ' minutes.');
}
return $input.all();

// One item per finished kit piece. The three renders complete independently, so
// this node can run more than once in a single execution — each batch carries
// the same kitCreditsTotal for the whole kit.
const all = $('Check validation').all().map((i) => i.json);
const kitCreditsTotal = all.reduce((n, d) => n + (Number(d.creditsRequired) || 0), 0);
const pieceCount = all.length;

const batch = $input.all();
// The post is remembered ONLY once every piece of the kit has come through, so
// a run that half-fails is retried in full rather than silently skipped. The
// counter is keyed by guid, so a different post always starts from zero.
// (Static data only persists on production executions; manual test runs
// re-render the newest post.)
const store = $getWorkflowStaticData('global');
const guid = all.length ? all[0].meta.postGuid : null;
if (guid) {
  const done = (store.kitProgress && store.kitProgress.guid === guid ? store.kitProgress.done : 0) + batch.length;
  if (done >= pieceCount) {
    store.lastGuid = guid;
    store.kitProgress = null;
  } else {
    store.kitProgress = { guid, done };
  }
}

return batch.map((item, i) => {
  const d = item.json;
  const url = typeof d.result === 'string' ? d.result : (d.result ? d.result.url : null);
  if (!url) {
    throw new Error('The completed render for the ' + d.meta.label + ' returned no URL.');
  }
  return {
    json: {
      rendered: true,
      kind: d.meta.kind,
      label: d.meta.label,
      format: d.meta.format,
      dimensions: d.meta.dimensions,
      seconds: d.meta.totalSeconds,
      videoUrl: url,
      jobId: d.jobId,
      creditsCharged: d.creditsRequired,
      kitCreditsTotal,
      kitPieces: d.meta.of,
      piece: d.meta.index + ' of ' + d.meta.of,
      postTitle: d.meta.postTitle,
      postLink: d.meta.postLink,
      brand: d.meta.brandName,
      domain: d.meta.domain,
      musicNote: d.meta.musicNote,
    },
    pairedItem: { item: i },
  };
});
